referenceSolutions.javascript:
function switchboardRingsEvenKeyCensus(links, k) {
  const a=links; let out=[];
  const n=a.length,dist=Array(n).fill(-1),queue=[];if(n){dist[0]=0;queue.push(0);}for(let h=0;h<queue.length;h++){const u=queue[h];for(let v=0;v<n;v++)if(a[u][v]&&dist[v]===-1){dist[v]=dist[u]+1;queue.push(v);}}out=dist;
  return out.filter(x=>x%2===0).length;
}

